@Service
public class LlmRouter {
    private final List<Provider> providers;            // 按优先级排序：primary, secondary, local
    private final CircuitBreakerRegistry registry;

    public String chat(String prompt) {
        RuntimeException last = null;
        for (Provider p : providers) {
            CircuitBreaker cb = registry.circuitBreaker(p.name());   // 每个提供商独立熔断
            if (!cb.tryAcquirePermission()) continue;               // 熔断打开，跳过
            long start = System.nanoTime();
            try {
                String r = p.client().prompt().user(p.adapt(prompt)).call().content();
                cb.onSuccess(System.nanoTime() - start, TimeUnit.NANOSECONDS);
                metrics.record(p.name(), start);
                return r;
            } catch (RuntimeException e) {
                cb.onError(System.nanoTime() - start, TimeUnit.NANOSECONDS, e);
                if (!isRetryable(e)) throw e;                       // 400 等不切换
                last = e;
                log.warn("provider {} failed, failover", p.name(), e);
            }
        }
        throw new LlmUnavailableException("all providers failed", last);
    }
}

